const transcript = [
  "Interviewer: Walk me through how you diagnose a well that suddenly loses production.",
  "Candidate: First I check the data. When a gas-lift well dropped about 30 percent, I pulled the wellhead pressures and the gas injection rate, compared them to the baseline, and saw injection pressure had risen. I suspected a valve issue, ran a flowing gradient survey, confirmed the operating valve had shifted, changed the injection depth, and production recovered to near baseline within two days.",
  "Interviewer: Tell me about optimizing production on a field you managed.",
  "Candidate: On one field the water cut was climbing. I reviewed the pattern well by well, identified two wells driving most of the water, adjusted their choke settings and reduced drawdown, and overall oil rate improved by roughly eight percent that month.",
  "Interviewer: How do you handle safety during a workover?",
  "Candidate: Safety is important, we always follow the permit.",
  "Interviewer: Anything else on safety, a specific example?",
  "Candidate: Not really a specific one, just that we follow the rules.",
  "Interviewer: What tools do you use for analysis?",
  "Candidate: I use nodal analysis software and Excel for the daily production reports and trend charts."
].join("\n");
const blueprintSnapshot = {
  blueprintId: "TEST-BP-0001",
  language: "en",
  competencies: [
    { competencyKey: "technical_troubleshooting", title: "Well Performance Diagnosis", priority: "critical", questionObjective: "Can the candidate structure a diagnosis of a production problem?", expectedEvidence: ["reads well data", "forms a hypothesis", "runs a test/survey", "verifies the fix"], redFlags: ["cannot explain a diagnostic approach", "gives contradictory examples"], scoreRubric: { "1": "cannot explain any diagnostic approach", "2": "vague, guesses without data", "3": "identifies common causes and basic steps", "4": "structured diagnosis using data with a concrete example", "5": "structured diagnosis with data, hypothesis, test, and verified result" }, followUpRules: ["ask for the specific measurement they checked"] },
    { competencyKey: "production_optimization", title: "Production Optimization", priority: "high", questionObjective: "Can the candidate improve output with measurable results?", expectedEvidence: ["identifies the constraint", "takes a specific action", "quantifies the result"], redFlags: ["no measurable results", "changes things without analysis"], scoreRubric: { "1": "no understanding of optimization", "2": "generic talk, no method", "3": "describes an approach without numbers", "4": "specific action with an approximate measurable result", "5": "clear method, specific action, and a quantified, verified result" }, followUpRules: ["ask for the number/percentage improvement"] },
    { competencyKey: "hse_awareness", title: "HSE Awareness", priority: "medium", questionObjective: "Does the candidate demonstrate real HSE practice?", expectedEvidence: ["cites a specific safety practice", "gives a real example"], redFlags: ["ignores safety", "treats safety as a formality"], scoreRubric: { "1": "dismisses safety", "2": "mentions safety only as a slogan", "3": "knows the basics (permits) but no concrete example", "4": "describes a specific safety practice applied", "5": "demonstrates safety leadership with a concrete example and outcome" }, followUpRules: ["ask for a specific incident they prevented"] }
  ]
};
return [{ json: { body: { candidateId: "TEST-STAGE3-0001", sessionId: "TEST-STAGE3-SESSION-0001", messageCount: 10, fullTranscript: transcript, jobCriteria: { title: "Production Engineer", seniority: "mid" }, blueprintSnapshot: blueprintSnapshot } } }];

